package com.zenitrade.controller; import com.zenitrade.entity.*; import com.zenitrade.repository.*; import com.zenitrade.service.CurrentUser; import jakarta.transaction.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/wallet") public class WalletController {private final CurrentUser cu;private final UserRepository users;private final WalletTransactionRepository txs;public WalletController(CurrentUser c,UserRepository u,WalletTransactionRepository t){cu=c;users=u;txs=t;}record Funds(String type,String method,BigDecimal amount){} @GetMapping Map<String,Object> get(){User u=cu.get();return Map.of("balance",u.virtualCash,"transactions",txs.findByUserIdOrderByCreatedAtDesc(u.id),"notice","Demo wallet only — no real money is processed.");} @PostMapping @Transactional WalletTransaction move(@RequestBody Funds f){if(f.amount()==null||f.amount().compareTo(BigDecimal.ZERO)<=0)throw new IllegalArgumentException("Enter a positive amount");User u=cu.get();boolean deposit="DEPOSIT".equalsIgnoreCase(f.type());if(!deposit&&u.virtualCash.compareTo(f.amount())<0)throw new IllegalArgumentException("Insufficient demo balance");u.virtualCash=deposit?u.virtualCash.add(f.amount()):u.virtualCash.subtract(f.amount());users.save(u);WalletTransaction x=new WalletTransaction();x.user=u;x.transactionType=deposit?"DEPOSIT":"WITHDRAW";x.method=f.method();x.amount=f.amount();x.referenceNote="Simulated "+x.transactionType.toLowerCase();return txs.save(x);} }
